// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/vacancies", wrapper.ListVacancies)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/vacancies", wrapper.CreateVacancy)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/vacancies/{vacancyId}", wrapper.GetVacancy)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/vacancies/{vacancyId}", wrapper.UpdateVacancy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/vacancies/{vacancyId}/archive", wrapper.ArchiveVacancy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/vacancies/{vacancyId}/restore", wrapper.RestoreVacancy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/vacancies/{vacancyId}/link/rotate", wrapper.RotateVacancyLink)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/vacancies/{vacancyId}/questions", wrapper.ListQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/vacancies/{vacancyId}/questions", wrapper.CreateQuestion)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/vacancies/{vacancyId}/questions/{questionId}", wrapper.DeleteQuestion)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/vacancies/{vacancyId}/questions/{questionId}", wrapper.UpdateQuestion)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/vacancies/{vacancyId}/questions/order", wrapper.ReorderQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/vacancies/public/{publicToken}", wrapper.GetVacancyWelcomeMessage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/evaluation-criteria/templates", wrapper.ListEvaluationCriterionTemplates)
	})

	return r
}

